package com.spirittreemakeover;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup(SpiritTreeMakeoverConfig.GROUP)
public interface SpiritTreeMakeoverConfig extends Config
{
	String GROUP = "spirittreemakeover";

	@ConfigItem(
		keyName = "skin",
		name = "Skin",
		description = "The tree every spirit tree is swapped for",
		position = 1
	)
	default TreeSkin skin()
	{
		return TreeSkin.CLASSIC_SPIRIT_TREE;
	}

	@Range(min = 10, max = 400)
	@ConfigItem(
		keyName = "scale",
		name = "Size %",
		description = "Size of the new tree, as a percentage of its normal in-game size",
		position = 2
	)
	default int scale()
	{
		return 100;
	}

	@ConfigItem(
		keyName = "animate",
		name = "Animate",
		description = "Play the tree's own animation, for the trees that have one",
		position = 3
	)
	default boolean animate()
	{
		return true;
	}

	@Range(min = 0, max = 64)
	@ConfigItem(
		keyName = "spinSpeed",
		name = "Spin speed",
		description = "How fast the tree turns on the spot. 0 keeps it facing the way the spirit tree does",
		position = 4
	)
	default int spinSpeed()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "changeHouseTree",
		name = "Change house spirit tree",
		description = "Also swap the spirit tree built in your player-owned house. Off by default, since the house tree already has its own looks",
		position = 5
	)
	default boolean changeHouseTree()
	{
		return false;
	}
}

package com.spirittreemakeover;

import com.google.inject.Provides;
import java.awt.Shape;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.DynamicObject;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Menu;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPCComposition;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.Renderable;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.Scene;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.hooks.DrawCallbacks;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.RenderCallback;
import net.runelite.client.callback.RenderCallbackManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Spirit Tree Makeover",
	description = "Swaps the plain spirit tree model for a more exciting tree from elsewhere in the game",
	tags = {"spirit", "tree", "model", "skin", "cosmetic", "transmog"}
)
@SuppressWarnings("deprecation") // RuneLiteObject radius: still what the scene uses to order large objects
public class SpiritTreeMakeoverPlugin extends Plugin implements RenderCallback
{
	private static final String SPIRIT_TREE = "Spirit tree";
	private static final String TRAVEL = "Travel";
	/** Every spirit tree you can build in a player-owned house, including the fairy ring combos and themed versions. */
	private static final Set<Integer> HOUSE_TREES = Set.of(
		ObjectID.POH_SPIRIT_TREE,
		ObjectID.POH_SPIRIT_RING,
		ObjectID.XMAS20_POH_SPIRIT_TREE,
		ObjectID.XMAS20_POH_SPIRIT_RING,
		ObjectID.LEAGUE_5_POH_SPIRIT_TREE,
		ObjectID.LEAGUE_5_POH_SPIRIT_RING
	);
	/** A face colour the game's renderers treat as "don't draw this face". */
	private static final int HIDDEN_FACE = -2;
	/** The lighting the game gives NPC models. */
	private static final int NPC_AMBIENT = 64;
	private static final int NPC_CONTRAST = 850;
	private static final String RUNELITE_GROUP = "runelite";
	private static final String HD_PACKAGE = "rs117.hd.";
	private static final short MAGIC_LEAVES_TEXTURE = 34;
	private static final short LEAVES_TEXTURE = 8;
	private static final String OBJECT_TARGET_COLOR = "<col=00ffff>";
	private static final MenuAction[] OBJECT_OPTIONS = {
		MenuAction.GAME_OBJECT_FIRST_OPTION,
		MenuAction.GAME_OBJECT_SECOND_OPTION,
		MenuAction.GAME_OBJECT_THIRD_OPTION,
		MenuAction.GAME_OBJECT_FOURTH_OPTION,
		MenuAction.GAME_OBJECT_FIFTH_OPTION,
	};

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private SpiritTreeMakeoverConfig config;

	@Inject
	private RenderCallbackManager renderCallbackManager;

	/** Whether an object id is, or can become (player-grown patches), a spirit tree. */
	private final Map<Integer, Boolean> candidateIds = new HashMap<>();
	private final Set<GameObject> candidates = new HashSet<>();
	private final Map<GameObject, RuneLiteObject> makeovers = new HashMap<>();
	/** Hashes of the original trees to skip drawing. Read on the render thread. */
	private final Set<Long> hidden = ConcurrentHashMap.newKeySet();
	/** Original face colours of the tree models whose faces are hidden, by model. */
	private final Map<Model, int[]> hiddenFaces = new IdentityHashMap<>();
	private final Map<Model, Integer> hiddenFaceUsers = new IdentityHashMap<>();
	/** The model whose faces were hidden for each replaced tree. */
	private final Map<GameObject, Model> hiddenModels = new HashMap<>();
	/** Skins whose model couldn't be built, so they aren't retried every tick. */
	private final Set<TreeSkin> failedSkins = EnumSet.noneOf(TreeSkin.class);
	/** Menu entries this plugin added for the tree under the mouse this frame. */
	private final List<MenuEntry> addedEntries = new ArrayList<>();

	@Override
	protected void startUp()
	{
		renderCallbackManager.register(this);
		// Renderers like the GPU plugin and 117 HD only ask which objects to hide while
		// building the scene, so reload it to swap trees that are already on screen.
		clientThread.invoke(this::reloadScene);
	}

	@Override
	protected void shutDown()
	{
		renderCallbackManager.unregister(this);
		clientThread.invoke(() ->
		{
			clearMakeovers();
			candidates.clear();
			candidateIds.clear();
			failedSkins.clear();
			reloadScene();
		});
	}

	@Provides
	SpiritTreeMakeoverConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SpiritTreeMakeoverConfig.class);
	}

	@Override
	public boolean drawObject(Scene scene, TileObject object)
	{
		return !hidden.contains(object.getHash());
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		consider(event.getGameObject());
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		GameObject object = event.getGameObject();
		candidates.remove(object);
		removeMakeover(object);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING
			|| event.getGameState() == GameState.LOGIN_SCREEN
			|| event.getGameState() == GameState.HOPPING)
		{
			clearMakeovers();
			candidates.clear();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		// A farming patch swaps between its growth stages without respawning, so
		// recheck whether each candidate is currently a usable spirit tree.
		for (GameObject object : candidates)
		{
			if (wantsMakeover(object) != makeovers.containsKey(object))
			{
				reloadScene();
				return;
			}
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		int speed = config.spinSpeed();
		if (speed == 0)
		{
			return;
		}

		for (RuneLiteObject makeover : makeovers.values())
		{
			makeover.setOrientation((makeover.getOrientation() + speed) & 2047);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		// Turning a renderer plugin like 117 HD on or off can change how a skin is built.
		boolean rendererToggled = RUNELITE_GROUP.equals(event.getGroup());
		if (!rendererToggled
			&& (!SpiritTreeMakeoverConfig.GROUP.equals(event.getGroup()) || "spinSpeed".equals(event.getKey())))
		{
			return;
		}

		// invokeLater, so a renderer that was just switched has finished taking over.
		clientThread.invokeLater(() ->
		{
			failedSkins.clear();
			if ("changeHouseTree".equals(event.getKey()))
			{
				reloadScene();
				return;
			}

			// The original trees stay hidden, so just dress the replacements in the new skin.
			for (RuneLiteObject makeover : makeovers.values())
			{
				if (!applySkin(makeover))
				{
					// Bring the original trees back rather than leave an empty spot.
					reloadScene();
					return;
				}
			}
		});
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		MenuEntry entry = event.getMenuEntry();

		// "Walk here" starts each frame's scene entries, so ours sit just above it,
		// right where the original tree's options would have gone.
		if (entry.getType() == MenuAction.WALK)
		{
			addedEntries.clear();
			addTreeEntries();
			return;
		}

		// If the game still offers the hidden tree's own options, drop the duplicates.
		for (MenuEntry added : addedEntries)
		{
			if (added.getType() == entry.getType()
				&& added.getIdentifier() == entry.getIdentifier()
				&& added.getParam0() == entry.getParam0()
				&& added.getParam1() == entry.getParam1())
			{
				client.getMenu().removeMenuEntry(entry);
				return;
			}
		}
	}

	private void reloadScene()
	{
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			client.setGameState(GameState.LOADING);
		}
	}

	private void consider(GameObject object)
	{
		if (candidateIds.computeIfAbsent(object.getId(), this::canBeSpiritTree))
		{
			candidates.add(object);
			if (wantsMakeover(object))
			{
				addMakeover(object);
			}
		}
	}

	private boolean canBeSpiritTree(int objectId)
	{
		ObjectComposition composition = client.getObjectDefinition(objectId);
		if (composition == null)
		{
			return false;
		}

		int[] impostorIds = composition.getImpostorIds();
		if (impostorIds == null)
		{
			return isSpiritTree(composition);
		}

		for (int impostorId : impostorIds)
		{
			if (impostorId != -1 && isSpiritTree(client.getObjectDefinition(impostorId)))
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Whether this is a spirit tree out in the world that you can travel from. Saplings,
	 * stumps and diseased trees in farming patches don't count.
	 */
	private static boolean isWorldSpiritTree(ObjectComposition composition)
	{
		return composition != null
			&& !HOUSE_TREES.contains(composition.getId())
			&& SPIRIT_TREE.equalsIgnoreCase(composition.getName())
			&& hasAction(composition, TRAVEL);
	}

	private static boolean hasAction(ObjectComposition composition, String option)
	{
		for (String action : composition.getActions())
		{
			if (option.equalsIgnoreCase(action))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean isSpiritTree(ObjectComposition composition)
	{
		return composition != null && (isWorldSpiritTree(composition) || HOUSE_TREES.contains(composition.getId()));
	}

	private boolean shouldReplace(ObjectComposition composition)
	{
		if (composition == null)
		{
			return false;
		}
		return HOUSE_TREES.contains(composition.getId()) ? config.changeHouseTree() : isWorldSpiritTree(composition);
	}

	private ObjectComposition activeComposition(GameObject object)
	{
		ObjectComposition composition = client.getObjectDefinition(object.getId());
		if (composition != null && composition.getImpostorIds() != null)
		{
			composition = composition.getImpostor();
		}
		return composition;
	}

	private boolean wantsMakeover(GameObject object)
	{
		return shouldReplace(activeComposition(object)) && !failedSkins.contains(config.skin());
	}

	private void addMakeover(GameObject object)
	{
		RuneLiteObject makeover = client.createRuneLiteObject();
		makeover.setLocation(object.getLocalLocation(), object.getPlane());
		makeover.setOrientation(object.getOrientation());
		if (!applySkin(makeover))
		{
			// Leave the original tree in place rather than making it vanish.
			return;
		}

		makeover.setActive(true);
		makeovers.put(object, makeover);
		hidden.add(object.getHash());
		hideFaces(object);
	}

	/** Dresses a replacement in the configured skin. Returns false if the skin's model couldn't be built. */
	private boolean applySkin(RuneLiteObject makeover)
	{
		TreeSkin skin = config.skin();
		if (failedSkins.contains(skin))
		{
			return false;
		}

		TreeSkin.Part[] parts = skin.getParts();
		TreeModelDefinition[] definitions = new TreeModelDefinition[parts.length];
		Model model = null;
		int animationId = skin.getNpcAnimationId();
		try
		{
			if (skin.isNpc())
			{
				model = buildNpcModel(skin);
			}
			else
			{
				boolean decoded = true;
				for (int i = 0; i < parts.length; i++)
				{
					definitions[i] = TreeModelDefinition.decode(
						client.getIndexConfig().loadData(TreeModelDefinition.OBJECT_ARCHIVE, parts[i].getObjectId()));
					decoded &= definitions[i] != null;
				}
				if (decoded)
				{
					model = buildModel(skin, definitions);
					animationId = definitions[0].animationId;
				}
			}
		}
		catch (RuntimeException e)
		{
			log.warn("Unable to build the {} model", skin, e);
		}
		if (model == null)
		{
			failedSkins.add(skin);
			return false;
		}

		makeover.setModel(model);
		// In the other modes, 117 HD lets scenery behind a big tree (benches, walls,
		// even the ground) paint over whatever part of the tree overlaps it on screen.
		makeover.setRenderMode(Renderable.RENDERMODE_SORTED);
		// Without this the scene treats the tree as one tile wide, and neighbouring tiles
		// drawn after it paint over everything that sticks out of that tile.
		makeover.setRadius(horizontalRadius(model));
		makeover.setDrawFrontTilesFirst(true);

		AnimationController animation = null;
		if (config.animate() && animationId != -1)
		{
			Animation loaded = client.loadAnimation(animationId);
			if (loaded != null)
			{
				animation = new AnimationController(client, loaded).setOnFinished(AnimationController::loop);
			}
		}
		makeover.setAnimationController(animation);
		return true;
	}

	private void removeMakeover(GameObject object)
	{
		RuneLiteObject makeover = makeovers.remove(object);
		if (makeover != null)
		{
			makeover.setActive(false);
		}
		hidden.remove(object.getHash());
		restoreFaces(object);
	}

	/**
	 * Hides every face of the original tree's model. The software renderer draws static
	 * scenery without asking the render callback, so this is what hides it there. Static
	 * models can be shared between identical trees, so the original colours are kept until
	 * the last tree using the model is restored.
	 */
	private void hideFaces(GameObject object)
	{
		Model model = staticModel(object);
		if (model == null || model.getFaceColors3() == null)
		{
			return;
		}

		hiddenModels.put(object, model);
		if (hiddenFaceUsers.merge(model, 1, Integer::sum) == 1)
		{
			int[] colors = model.getFaceColors3();
			hiddenFaces.put(model, colors.clone());
			Arrays.fill(colors, HIDDEN_FACE);
		}
	}

	/**
	 * The model an object always draws with, or null if it builds a new one each frame.
	 * Some trees, like the Grand Exchange one, are stored as animated objects even though
	 * they never animate, and those keep drawing the same model.
	 */
	private static Model staticModel(GameObject object)
	{
		Renderable renderable = object.getRenderable();
		if (renderable instanceof Model)
		{
			return (Model) renderable;
		}
		if (renderable instanceof DynamicObject && ((DynamicObject) renderable).getAnimation() == null)
		{
			return ((DynamicObject) renderable).getModelZbuf();
		}
		// Animated trees are hidden by the render callback every frame.
		return null;
	}

	private void restoreFaces(GameObject object)
	{
		Model model = hiddenModels.remove(object);
		if (model == null)
		{
			return;
		}

		int users = hiddenFaceUsers.merge(model, -1, Integer::sum);
		if (users <= 0)
		{
			hiddenFaceUsers.remove(model);
			int[] colors = hiddenFaces.remove(model);
			System.arraycopy(colors, 0, model.getFaceColors3(), 0, colors.length);
		}
	}

	private void clearMakeovers()
	{
		makeovers.values().forEach(makeover -> makeover.setActive(false));
		makeovers.clear();
		hidden.clear();
		hiddenFaces.forEach((model, colors) -> System.arraycopy(colors, 0, model.getFaceColors3(), 0, colors.length));
		hiddenFaces.clear();
		hiddenFaceUsers.clear();
		hiddenModels.clear();
		addedEntries.clear();
	}

	/**
	 * Builds the skin's model the same way the game builds each object's (merged parts,
	 * recoloured, scaled and offset), then puts the pieces together and lights them.
	 */
	private Model buildModel(TreeSkin skin, TreeModelDefinition[] definitions)
	{
		TreeSkin.Part[] parts = skin.getParts();
		int modelCount = 0;
		for (TreeModelDefinition definition : definitions)
		{
			int[] modelIds = definition.centrepieceModels();
			if (modelIds == null)
			{
				return null;
			}
			modelCount += modelIds.length;
		}

		List<ModelData> pieces = new ArrayList<>();
		for (int i = 0; i < parts.length; i++)
		{
			TreeModelDefinition definition = definitions[i];
			List<ModelData> models = new ArrayList<>();
			for (int modelId : definition.centrepieceModels())
			{
				ModelData model = client.loadModelData(modelId);
				if (model == null)
				{
					return null;
				}
				// Trees grown in farming patches include the patch's flat soil square, which
				// would look out of place under a spirit tree that isn't in a patch.
				if (modelCount == 1 || !isFlat(model))
				{
					models.add(model);
				}
			}
			if (models.isEmpty())
			{
				continue;
			}

			ModelData piece = editableCopy(client.mergeModels(models.toArray(new ModelData[0])));
			if (definition.recolorFrom != null)
			{
				for (int j = 0; j < definition.recolorFrom.length; j++)
				{
					piece.recolor(definition.recolorFrom[j], definition.recolorTo[j]);
				}
			}
			if (definition.retextureFrom != null && piece.getFaceTextures() != null)
			{
				for (int j = 0; j < definition.retextureFrom.length; j++)
				{
					piece.retexture(definition.retextureFrom[j], definition.retextureTo[j]);
				}
			}
			if (piece.getFaceTextures() != null && isHdActive())
			{
				// 117 HD skips some faces using the magic tree's sparkling leaves when they
				// aren't on real scenery, leaving holes in the canopy. Plain leaves draw fine.
				piece.retexture(MAGIC_LEAVES_TEXTURE, LEAVES_TEXTURE);
			}
			piece.scale(definition.scaleX, definition.scaleHeight, definition.scaleY);
			int[] offset = turn(piece, parts[i].getQuarterTurns(), parts[i].getX(), parts[i].getZ());
			piece.translate(definition.offsetX + offset[0], definition.offsetHeight + parts[i].getHeight(),
				definition.offsetY + offset[1]);
			pieces.add(piece);
		}
		if (pieces.isEmpty())
		{
			return null;
		}

		ModelData model = pieces.size() == 1
			? pieces.get(0)
			: client.mergeModels(pieces.toArray(new ModelData[0])).shallowCopy().cloneVertices();
		int size = 128 * skin.getBaseScale() / 100 * config.scale() / 100;
		model.scale(size, size, size);

		TreeModelDefinition lighting = definitions[0];
		return model.light(lighting.ambient + 64, lighting.contrast + 768, -50, -10, -50);
	}

	/**
	 * Turns a piece a number of quarter turns about its origin, and returns its (x, z)
	 * offset turned the same way. The direction of the game's turn is read off one of
	 * the piece's own vertices rather than assumed.
	 */
	private static int[] turn(ModelData piece, int quarterTurns, int x, int z)
	{
		for (int t = 0; t < quarterTurns; t++)
		{
			float[] xs = piece.getVerticesX();
			float[] zs = piece.getVerticesZ();
			int probe = 0;
			while (probe < piece.getVerticesCount() - 1 && xs[probe] == 0 && zs[probe] == 0)
			{
				probe++;
			}
			float beforeX = xs[probe];
			float beforeZ = zs[probe];

			piece.rotateY90Ccw();

			// A quarter turn sends (x, z) to either (z, -x) or (-z, x).
			boolean toZMinusX = piece.getVerticesX()[probe] == beforeZ && piece.getVerticesZ()[probe] == -beforeX;
			int turnedX = toZMinusX ? z : -z;
			int turnedZ = toZMinusX ? -x : x;
			x = turnedX;
			z = turnedZ;
		}
		return new int[]{x, z};
	}

	private boolean isHdActive()
	{
		DrawCallbacks drawCallbacks = client.getDrawCallbacks();
		return drawCallbacks != null && drawCallbacks.getClass().getName().startsWith(HD_PACKAGE);
	}

	/** Builds an NPC skin the way the game builds the NPC: merged parts, recoloured and scaled. */
	private Model buildNpcModel(TreeSkin skin)
	{
		NPCComposition npc = client.getNpcDefinition(skin.getNpcId());
		if (npc == null || npc.getModels() == null)
		{
			return null;
		}

		int[] modelIds = npc.getModels();
		ModelData[] parts = new ModelData[modelIds.length];
		for (int i = 0; i < modelIds.length; i++)
		{
			parts[i] = client.loadModelData(modelIds[i]);
			if (parts[i] == null)
			{
				return null;
			}
		}

		ModelData model = editableCopy(client.mergeModels(parts));
		short[] from = npc.getColorToReplace();
		short[] to = npc.getColorToReplaceWith();
		if (from != null && to != null)
		{
			for (int i = 0; i < Math.min(from.length, to.length); i++)
			{
				model.recolor(from[i], to[i]);
			}
		}

		int percent = skin.getBaseScale() * config.scale() / 100;
		int width = npc.getWidthScale() * percent / 100;
		model.scale(width, npc.getHeightScale() * percent / 100, width);
		return model.light(NPC_AMBIENT, NPC_CONTRAST, ModelData.DEFAULT_X, ModelData.DEFAULT_Y, ModelData.DEFAULT_Z);
	}

	/** Copies a model so it can be changed without touching the game's cached copy. */
	private static ModelData editableCopy(ModelData model)
	{
		ModelData copy = model.shallowCopy().cloneVertices().cloneColors();
		return copy.getFaceTextures() != null ? copy.cloneTextures() : copy;
	}

	/** How far the model reaches from its centre across the ground, in local units. */
	private static int horizontalRadius(Model model)
	{
		float radius = Perspective.LOCAL_HALF_TILE_SIZE;
		float[] xs = model.getVerticesX();
		float[] zs = model.getVerticesZ();
		for (int i = 0; i < model.getVerticesCount(); i++)
		{
			radius = Math.max(radius, Math.max(Math.abs(xs[i]), Math.abs(zs[i])));
		}
		return (int) Math.ceil(radius);
	}

	private static boolean isFlat(ModelData model)
	{
		for (float y : model.getVerticesY())
		{
			if (y != 0)
			{
				return false;
			}
		}
		return true;
	}

	private void addTreeEntries()
	{
		if (makeovers.isEmpty())
		{
			return;
		}

		Point mouse = client.getMouseCanvasPosition();
		for (Map.Entry<GameObject, RuneLiteObject> entry : makeovers.entrySet())
		{
			GameObject object = entry.getKey();
			RuneLiteObject makeover = entry.getValue();
			Model model = makeover.getModel();
			LocalPoint location = makeover.getLocation();
			WorldView worldView = object.getWorldView();
			if (model == null || location == null || worldView == null)
			{
				continue;
			}

			Shape clickbox = Perspective.getClickbox(client, worldView, model, makeover.getOrientation(),
				location.getX(), location.getY(), Perspective.getTileHeight(client, location, object.getPlane()));
			if (clickbox != null && clickbox.contains(mouse.getX(), mouse.getY()))
			{
				addObjectEntries(object, worldView);
				return;
			}
		}
	}

	/** Recreates the menu the game builds for an object: Examine at the bottom, then options last to first. */
	private void addObjectEntries(GameObject object, WorldView worldView)
	{
		ObjectComposition composition = activeComposition(object);
		if (composition == null)
		{
			return;
		}

		String target = OBJECT_TARGET_COLOR + composition.getName();
		Point sceneLocation = object.getSceneMinLocation();

		addObjectEntry("Examine", target, MenuAction.EXAMINE_OBJECT, object, sceneLocation, worldView);

		String[] actions = composition.getActions();
		for (int i = Math.min(actions.length, OBJECT_OPTIONS.length) - 1; i >= 0; i--)
		{
			if (actions[i] != null)
			{
				addObjectEntry(actions[i], target, OBJECT_OPTIONS[i], object, sceneLocation, worldView);
			}
		}
	}

	private void addObjectEntry(String option, String target, MenuAction type, GameObject object,
		Point sceneLocation, WorldView worldView)
	{
		Menu menu = client.getMenu();
		MenuEntry entry = menu.createMenuEntry(-1)
			.setOption(option)
			.setTarget(target)
			.setType(type)
			.setIdentifier(object.getId())
			.setParam0(sceneLocation.getX())
			.setParam1(sceneLocation.getY())
			.setWorldViewId(worldView.getId());
		addedEntries.add(entry);
	}
}

package com.spirittreemakeover;

import java.nio.charset.Charset;

/**
 * The parts of an object definition needed to rebuild its model. RuneLite doesn't
 * expose an object's model ids, so this decodes the raw definition from the
 * game's config index, following the cache library's ObjectLoader.
 */
final class TreeModelDefinition
{
	/** Config index archive holding object definitions. */
	static final int OBJECT_ARCHIVE = 6;

	private static final int CENTREPIECE_TYPE = 10;
	private static final Charset CP1252 = Charset.forName("windows-1252");

	String name;
	int[] models;
	int[] types;
	short[] recolorFrom;
	short[] recolorTo;
	short[] retextureFrom;
	short[] retextureTo;
	int sizeX = 1;
	int sizeY = 1;
	int animationId = -1;
	int ambient;
	int contrast;
	int scaleX = 128;
	int scaleHeight = 128;
	int scaleY = 128;
	int offsetX;
	int offsetHeight;
	int offsetY;

	private final byte[] data;
	private int pos;

	private TreeModelDefinition(byte[] data)
	{
		this.data = data;
	}

	/**
	 * @return the decoded definition, or null if it uses an opcode this doesn't
	 * understand, such as one added in a game update after this was written
	 */
	static TreeModelDefinition decode(byte[] data)
	{
		if (data == null)
		{
			return null;
		}

		TreeModelDefinition def = new TreeModelDefinition(data);
		try
		{
			for (int opcode = def.u8(); opcode != 0; opcode = def.u8())
			{
				if (!def.read(opcode))
				{
					return null;
				}
			}
		}
		catch (ArrayIndexOutOfBoundsException e)
		{
			return null;
		}
		return def;
	}

	/** Model ids that make up the object when placed as a normal standalone object. */
	int[] centrepieceModels()
	{
		if (models == null)
		{
			return null;
		}
		if (types == null)
		{
			return models;
		}

		for (int i = 0; i < types.length; i++)
		{
			if (types[i] == CENTREPIECE_TYPE)
			{
				return new int[]{models[i]};
			}
		}
		return new int[]{models[0]};
	}

	private boolean read(int opcode)
	{
		switch (opcode)
		{
			case 1:
			case 6:
			{
				int length = u8();
				if (length > 0)
				{
					models = new int[length];
					types = new int[length];
					for (int i = 0; i < length; i++)
					{
						models[i] = opcode == 1 ? u16() : s32();
						types[i] = u8();
					}
				}
				break;
			}
			case 5:
			case 7:
			{
				int length = u8();
				if (length > 0)
				{
					types = null;
					models = new int[length];
					for (int i = 0; i < length; i++)
					{
						models[i] = opcode == 5 ? u16() : s32();
					}
				}
				break;
			}
			case 2:
				name = string();
				break;
			case 14:
				sizeX = u8();
				break;
			case 15:
				sizeY = u8();
				break;
			case 24:
				animationId = u16();
				if (animationId == 0xFFFF)
				{
					animationId = -1;
				}
				break;
			case 29:
				ambient = data[pos++];
				break;
			case 39:
				contrast = data[pos++] * 25;
				break;
			case 40:
			case 41:
			{
				int length = u8();
				short[] from = new short[length];
				short[] to = new short[length];
				for (int i = 0; i < length; i++)
				{
					from[i] = (short) u16();
					to[i] = (short) u16();
				}
				if (opcode == 40)
				{
					recolorFrom = from;
					recolorTo = to;
				}
				else
				{
					retextureFrom = from;
					retextureTo = to;
				}
				break;
			}
			case 65:
				scaleX = u16();
				break;
			case 66:
				scaleHeight = u16();
				break;
			case 67:
				scaleY = u16();
				break;
			case 70:
				offsetX = (short) u16();
				break;
			case 71:
				offsetHeight = (short) u16();
				break;
			case 72:
				offsetY = (short) u16();
				break;
			// Flags with no data
			case 17:
			case 18:
			case 21:
			case 22:
			case 23:
			case 27:
			case 62:
			case 64:
			case 73:
			case 74:
			case 89:
			case 90:
			case 94:
				break;
			// One byte
			case 19:
			case 28:
			case 69:
			case 75:
			case 81:
			case 91:
			case 95:
			case 96:
				pos += 1;
				break;
			// Two bytes
			case 42:
			case 61:
			case 68:
			case 82:
				pos += 2;
				break;
			case 30:
			case 31:
			case 32:
			case 33:
			case 34:
				string();
				break;
			case 77:
			case 92:
			{
				pos += opcode == 77 ? 4 : 6;
				int length = u8();
				pos += (length + 1) * 2;
				break;
			}
			case 78:
				pos += 4;
				break;
			case 79:
			{
				pos += 6;
				int length = u8();
				pos += length * 2;
				break;
			}
			case 93:
				pos += 6;
				break;
			case 100:
				pos += 2;
				string();
				break;
			case 101:
				pos += 13;
				string();
				break;
			case 102:
				pos += 15;
				string();
				break;
			case 249:
			{
				int count = u8();
				for (int i = 0; i < count; i++)
				{
					boolean isString = u8() == 1;
					pos += 3;
					if (isString)
					{
						string();
					}
					else
					{
						pos += 4;
					}
				}
				break;
			}
			default:
				return false;
		}
		return true;
	}

	private int u8()
	{
		return data[pos++] & 0xFF;
	}

	private int u16()
	{
		return u8() << 8 | u8();
	}

	private int s32()
	{
		return u16() << 16 | u16();
	}

	private String string()
	{
		int start = pos;
		while (data[pos] != 0)
		{
			pos++;
		}
		return new String(data, start, pos++ - start, CP1252);
	}
}

package com.spirittreemakeover;

import lombok.Getter;
import lombok.Value;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.gameval.ObjectID;

/**
 * A tree the spirit tree can be swapped for. Each skin borrows the model, colours
 * and animation of an existing tree object or tree-like NPC in the game.
 */
@Getter
public enum TreeSkin
{
	CLASSIC_SPIRIT_TREE("Classic spirit tree", ObjectID.SPIRITTREE_BIG_2OPS),
	PRIFDDINAS_SPIRIT_TREE("Prifddinas spirit tree", ObjectID.SPIRITTREE_PRIF_2OPS),
	POISON_WASTE_SPIRIT_TREE("Poison Waste spirit tree", ObjectID.POG_SPIRIT_TREE_ALIVE_STATIC),
	CHRISTMAS_SPIRIT_TREE("Christmas spirit tree", ObjectID.XMAS20_POH_SPIRIT_TREE),
	RAGING_ECHOES_SPIRIT_TREE("Raging Echoes spirit tree", ObjectID.LEAGUE_5_POH_SPIRIT_TREE),
	OAK("Oak tree", ObjectID.OAKTREE),
	WILLOW("Willow tree", ObjectID.WILLOWTREE),
	MAPLE("Maple tree", ObjectID.MAPLETREE),
	YEW("Yew tree", ObjectID.YEWTREE),
	MAGIC("Magic tree", ObjectID.MAGICTREE),
	REDWOOD("Redwood tree", 35, redwoodParts()),
	TEAK("Teak tree", ObjectID.TEAKTREE),
	MAHOGANY("Mahogany tree", ObjectID.MAHOGANYTREE),
	CAMPHOR("Camphor tree", ObjectID.CAMPHOR_TREE),
	IRONWOOD("Ironwood tree", ObjectID.IRONWOOD_TREE),
	ROSEWOOD("Rosewood tree", ObjectID.ROSEWOOD_TREE),
	CRYSTAL("Crystal tree", ObjectID.CRYSTAL_TREE_TREE_FULLYGROWN),
	BLOODWOOD("Bloodwood tree", ObjectID.BLOODWOOD_TREE_DEFAULT01),
	BLISTERWOOD("Blisterwood tree", ObjectID.BLISTERWOOD_TREE),
	DRAMEN("Dramen tree", ObjectID.DRAMENTREE),
	DREAM("Dream tree", ObjectID.LUNAR_DREAM_DREAM_TREE),
	ARCTIC_PINE("Arctic pine", ObjectID.ARCTIC_PINE),
	SNOWY_EVERGREEN("Snowy evergreen", ObjectID.EVERGREEN_VSNOWY_LARGE),
	ACHEY("Achey tree", ObjectID.ACHEY_TREE),
	JUNGLE("Jungle tree", ObjectID.KHARAZI_JUNGLE_TREE_LOGS),
	HOLLOW("Hollow tree", ObjectID.HOLLOW_TREE_BIG),
	WINDSWEPT("Windswept tree", ObjectID.OLAF_WINDSWEPT_TREE),
	DEAD("Dead tree", ObjectID.DEADTREE1),
	ENT("Ent", NpcID.WCGUILD_ENT, AnimationID.NPC_ENT_READY_01, 150),
	TREE_SPIRIT("Tree spirit", NpcID.TREE_SPIRIT, AnimationID.GHOST_UPDATE_NORMAL_READY, 200),
	HESPORI("Hespori", NpcID.HESPORI, AnimationID.HESPORI_READY, 100),
	HESPORI_ECHO("Hespori (echo)", NpcID.LEAGUE_6_HESPORI, AnimationID.HESPORI_READY, 100),
	HESPORI_QUEST("Hespori (quest)", NpcID.TOBQUEST_HESPORI, AnimationID.HESPORI_READY, 100),
	HESPORI_PLANT("Hespori plant", ObjectID.HESPORI_PLANT_FULLYGROWN),
	HESPORI_SPROUT("Blooming Hespori sprout", ObjectID.KEBOS_FARMING_GUILD_HESPORI_GROWN),
	TANGLEROOT("Tangleroot", NpcID.SKILLPET_FARMING, AnimationID.TANGLEROOT_IDLE, 400),
	ODD_TREE("Odd tree", NpcID.SOTFA_FOREST_NASTY_TREE, -1, 150);

	/**
	 * One object the skin is built from, placed relative to the skin's centre in local
	 * units. The piece and its offset are both turned a number of quarter turns about
	 * the skin's centre, so one corner piece can be reused for every corner.
	 */
	@Value
	static class Part
	{
		int objectId;
		int x;
		/** Up is negative, as in the game's models. */
		int height;
		int z;
		int quarterTurns;
	}

	private final String displayName;
	/** Size, in percent of the game's own size, that a Size % of 100 stands for. */
	private final int baseScale;
	private final Part[] parts;
	/** The NPC whose model this skin wears, or -1 for a skin built from objects. */
	private final int npcId;
	/** Idle animation for an NPC skin, or -1. Objects carry their own. */
	private final int npcAnimationId;

	TreeSkin(String displayName, int objectId)
	{
		this(displayName, 100, new Part(objectId, 0, 0, 0, 0));
	}

	TreeSkin(String displayName, int baseScale, Part... parts)
	{
		this.displayName = displayName;
		this.baseScale = baseScale;
		this.parts = parts;
		this.npcId = -1;
		this.npcAnimationId = -1;
	}

	TreeSkin(String displayName, int npcId, int npcAnimationId, int baseScale)
	{
		this.displayName = displayName;
		this.baseScale = baseScale;
		this.parts = new Part[0];
		this.npcId = npcId;
		this.npcAnimationId = npcAnimationId;
	}

	boolean isNpc()
	{
		return npcId != -1;
	}

	/**
	 * A grown redwood is a stack of pieces: a 3x3 grid of trunk pieces 8 tiles across,
	 * a narrower 3x3 grid on the floor above, and a crown made of one corner piece used
	 * four times. Grid pieces are numbered row by row, starting with the row furthest
	 * along the model's z axis.
	 */
	private static Part[] redwoodParts()
	{
		int[] bottom = {
			ObjectID.REDWOOD_TREE_FULLYGROWN_0_1, ObjectID.REDWOOD_TREE_FULLYGROWN_0_2, ObjectID.REDWOOD_TREE_FULLYGROWN_0_3,
			ObjectID.REDWOOD_TREE_FULLYGROWN_0_4, ObjectID.REDWOOD_TREE_FULLYGROWN_0_5, ObjectID.REDWOOD_TREE_FULLYGROWN_0_6,
			ObjectID.REDWOOD_TREE_FULLYGROWN_0_7, ObjectID.REDWOOD_TREE_FULLYGROWN_0_8, ObjectID.REDWOOD_TREE_FULLYGROWN_0_9,
		};
		int[] middle = {
			ObjectID.REDWOOD_TREE_FULLYGROWN_1_1, ObjectID.REDWOOD_TREE_FULLYGROWN_1_2, ObjectID.REDWOOD_TREE_FULLYGROWN_1_3,
			ObjectID.REDWOOD_TREE_FULLYGROWN_1_4, ObjectID.REDWOOD_TREE_FULLYGROWN_1_5, ObjectID.REDWOOD_TREE_FULLYGROWN_1_6,
			ObjectID.REDWOOD_TREE_FULLYGROWN_1_7, ObjectID.REDWOOD_TREE_FULLYGROWN_1_8, ObjectID.REDWOOD_TREE_FULLYGROWN_1_9,
		};
		// Bottom pieces are 3, 2 and 3 tiles wide; the middle floor's are all 2.
		int[] bottomCentres = {-320, 0, 320};
		int[] middleCentres = {-256, 0, 256};
		int bottomHeight = 896;
		int middleHeight = 668;

		Part[] parts = new Part[22];
		for (int i = 0; i < 9; i++)
		{
			int column = i % 3;
			int row = i / 3;
			parts[i] = new Part(bottom[i], bottomCentres[column], 0, -bottomCentres[row], 0);
			parts[9 + i] = new Part(middle[i], middleCentres[column], -bottomHeight, -middleCentres[row], 0);
		}
		// The crown corner's peak is at its (+x, -z) corner, which goes in the middle.
		for (int turns = 0; turns < 4; turns++)
		{
			parts[18 + turns] = new Part(ObjectID.REDWOOD_TREE_FULLYGROWN_2_1, -256, -bottomHeight - middleHeight, 256, turns);
		}
		return parts;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

